 async function saveCategory(){if(!category.name?.trim()){setNotice('نام دسته‌بندی را وارد کنید.');return;}const name=category.name.trim();const payload={...category,name,slug:(category.slug||'').trim()||('category-'+Date.now()),sort_order:Number(category.sort_order),is_active:category.is_active!==false};setSaving(true);try{const q=category.id?supabase.from('categories').update(payload).eq('id',category.id):supabase.from('categories').insert(payload);const {error}=await q;if(error)throw error;setData(d=>{const rows=d.categories||[];return {...d,categories:category.id?rows.map(row=>row.id===category.id?{...row,...payload}:row):[...rows,{...payload,id:'local-'+Date.now()}]};});setSearch('');setModal(null);setNotice('دسته‌بندی ذخیره شد و به فهرست دسته‌های موجود اضافه شد.');setPreviewVersion(v=>v+1);await load();}catch(error){setNotice('ذخیره دسته‌بندی ناموفق بود: '+(error?.message||'خطای نامشخص'));}finally{setSaving(false);}}
 async function saveSettings(){if(!settings.store_name?.trim()||!settings.currency?.trim()){setNotice('نام فروشگاه و واحد پول را کامل کنید.');return;}if(Number(settings.default_markup_percent)<0){setNotice('درصد اجرت/سود نمی‌تواند منفی باشد.');return;}setSaving(true);try{const payload={...settings,id:1,default_markup_percent:Number(settings.default_markup_percent),updated_at:new Date().toISOString()};const {error}=await supabase.from('store_settings').upsert(payload,{onConflict:'id'});if(error)throw error;setSettings(payload);setNotice('تنظیمات فروشگاه ذخیره شد.');}catch(error){setNotice('ذخیره تنظیمات ناموفق بود: '+(error?.message||'خطای ناشناخته'));}finally{setSaving(false);}}
