function Field({label,value,change,type='text',step,min,max}){return <label>{label}<input type={type} step={step??(type==='number'?'any':undefined)} min={min} max={max} value={value??''} onChange={e=>change(e.target.value)}/></label>}
function Toolbar({search,setSearch,add,label}){return <div className="admin-toolbar"><input placeholder="جست‌وجو…" value={search} onChange={e=>setSearch(e.target.value)}/><button onClick={add}>＋ {label}</button></div>}
const orderStatusLabels={pending:'در انتظار بررسی',awaiting_payment:'در انتظار پرداخت',paid:'پرداخت‌شده',processing:'در حال آماده‌سازی',shipped:'ارسال‌شده',completed:'تکمیل‌شده',cancelled:'لغوشده',payment_failed:'پرداخت ناموفق'};
const orderStatusTransitions={pending:['awaiting_payment','cancelled','payment_failed'],awaiting_payment:['cancelled','payment_failed'],paid:['processing'],processing:['shipped'],shipped:['completed'],completed:[],cancelled:[],payment_failed:[]};
function Orders({rows,update,archive,remove,archivedView,busy}){return <div className="admin-table-wrap"><table><thead><tr><th>شماره</th><th>مشتری</th><th>مبلغ کل</th><th>وضعیت</th><th>تاریخ</th><th>تغییر وضعیت</th><th>ریز فاکتور</th><th>مدیریت سابقه</th></tr></thead><tbody>{rows.length?rows.map(o=>{const canArchive=o.status==='completed'&&Boolean(o.paid_at);const canDelete=o.status==='cancelled'&&!o.paid_at&&!o.payment_reference&&!o.payment_provider;return <tr key={o.id}><td>#{o.order_number}</td><td>{o.customer_name}<small>{o.customer_phone}</small></td><td>{money(o.total_toman)} تومان</td><td><span className={'admin-status-pill status-'+o.status}>{orderStatusLabels[o.status]||o.status}</span></td><td>{new Date(o.created_at).toLocaleDateString('fa-IR')}</td><td><select value={o.status} disabled={!(orderStatusTransitions[o.status]||[]).length||Boolean(o.archived_at)} onChange={e=>update(o.id,o.status,e.target.value)}><option value={o.status}>{orderStatusLabels[o.status]||o.status}</option>{(orderStatusTransitions[o.status]||[]).map(s=><option key={s} value={s}>{orderStatusLabels[s]}</option>)}</select></td><td><details className="admin-invoice-details"><summary>مشاهده فاکتور</summary><div className="admin-invoice-lines">{(o.order_items||[]).map(item=><article key={item.id}><b>{item.product_name} × {money(item.quantity)}</b>{item.pricing_mode==='auto'?<><span>اصل طلا: {money(item.gold_value_toman)} تومان</span><span>اجرت ساخت: {money(item.labor_toman)} تومان</span><span>سود فروشنده: {money(item.seller_profit_toman)} تومان</span><span>حق‌العمل: {money(item.commission_toman)} تومان</span><span>مالیات: {money(item.vat_toman)} تومان</span></>:<span>قیمت محصول به‌صورت دستی ثبت شده؛ ریز اجزا هنگام سفارش موجود نبوده است.</span>}<strong>جمع ردیف: {money(item.line_total_toman)} تومان</strong></article>)}{!(o.order_items||[]).length&&<span>اقلام این سفارش بارگذاری نشده‌اند.</span>}</div></details></td><td>{archivedView?<button type="button" disabled={busy} onClick={()=>archive(o.id,false)}>بازگردانی</button>:canArchive?<button type="button" disabled={busy} onClick={()=>archive(o.id,true)}>بایگانی</button>:canDelete?<button type="button" className="danger" disabled={busy} onClick={()=>remove(o)}>حذف کامل</button>:<small>—</small>}</td></tr>;}):<tr><td colSpan="8" className="admin-empty-cell">{archivedView?'سفارش بایگانی‌شده‌ای وجود ندارد.':'سفارشی برای نمایش وجود ندارد.'}</td></tr>}</tbody></table></div>}
